package gin

import (
	"errors"
	"fmt"
	"testing"
)

type probeCustomErr struct{ msg string }

func (e probeCustomErr) Error() string { return e.msg }

// compile-time assertions (d)
var _ interface{ Unwrap() error } = Error{}
var _ interface{ Unwrap() error } = &Error{}

func TestProbeErrorUnwrap(t *testing.T) {
	innerErr := probeCustomErr{"inner"}

	// (a) pointer value
	perr := fmt.Errorf("w: %w", &Error{Err: innerErr, Type: ErrorTypeAny})
	if !errors.Is(perr, innerErr) {
		t.Errorf("(a) errors.Is(ptr) = false, want true")
	}
	var got probeCustomErr
	if !errors.As(perr, &got) {
		t.Errorf("(a) errors.As(ptr) = false, want true")
	}
	if errors.Unwrap(&Error{Err: innerErr}) != error(innerErr) {
		t.Errorf("(c) errors.Unwrap(&Error{}) wrong")
	}

	// (b) value Error
	verr := fmt.Errorf("w: %w", Error{Err: innerErr, Type: ErrorTypeAny})
	if !errors.Is(verr, innerErr) {
		t.Errorf("(b) errors.Is(value) = false, want true")
	}
	var got2 probeCustomErr
	if !errors.As(verr, &got2) {
		t.Errorf("(b) errors.As(value) = false, want true")
	}

	// (c) Unwrap on value
	if errors.Unwrap(Error{Err: innerErr}) != error(innerErr) {
		t.Errorf("(c) errors.Unwrap(Error{}) wrong")
	}

	// (d) runtime interface checks
	if _, ok := any(Error{}).(interface{ Unwrap() error }); !ok {
		t.Errorf("(d) Error{} does not implement interface{ Unwrap() error }")
	}
	if _, ok := any(&Error{}).(interface{ Unwrap() error }); !ok {
		t.Errorf("(d) &Error{} does not implement interface{ Unwrap() error }")
	}
}

// Unwrap returns the wrapped error, to allow interoperability with errors.Is(), errors.As() and errors.Unwrap()
func (msg Error) Unwrap() error {
	return msg.Err
}

